def models(keywords=None, status=None, tag=None, provider=None, sort_by=None, sort_order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0309000" if __import__("os").path.isdir("./environment_mix/0309000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur.strip():
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===").decode("utf-8")
            if not raw.startswith("o:"):
                return None
            off = int(raw.split(":", 1)[1])
            if off < 0:
                return None
            return off
        except Exception:
            return None

    def _record_call(endpoint, api_key_id, project_id, status_code):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int((time.time() - t0) * 1000)
        logs.append({
            "id": "req_" + hashlib.sha256(f"{endpoint}|{api_key_id}|{project_id}|{now}|{len(logs)}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "project_id": project_id,
            "status": status_code,
            "latency_ms": latency_ms,
            "created_at": now
        })
        _save("request_logs.json", logs)

    def _choose_auth_context():
        api_keys = _load("api_keys.json")
        projects = _load("projects.json")
        if not isinstance(api_keys, list):
            api_keys = []
        if not isinstance(projects, list):
            projects = []
        proj_by_id = {p.get("id"): p for p in projects if isinstance(p, dict)}
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            pid = k.get("project_id")
            p = proj_by_id.get(pid)
            if not p or p.get("status") != "active":
                continue
            # ensure quotas present and sane types
            if not isinstance(k.get("quota_requests_per_minute"), int):
                continue
            return k, p
        return None, None

    def _enforce_rate_limit(api_key_row):
        api_key_id = api_key_row.get("id")
        qpm = api_key_row.get("quota_requests_per_minute")
        if not isinstance(qpm, int) or qpm < 1:
            return _err("UNAUTHORIZED", "No valid quota configured for API key.")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        if cnt >= qpm:
            return _err("RATE_LIMIT", "Rate limit exceeded.", limit=qpm, window_seconds=60)
        return None

    # Validate inputs
    if keywords is not None and not isinstance(keywords, str):
        return _err("VALIDATION_ERROR", "`keywords` must be a string.")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deprecated", "disabled"):
            return _err("VALIDATION_ERROR", "`status` must be one of: active, deprecated, disabled.")
    if tag is not None and not isinstance(tag, str):
        return _err("VALIDATION_ERROR", "`tag` must be a string.")
    if provider is not None:
        if not isinstance(provider, str) or provider not in ("fal.ai",):
            return _err("VALIDATION_ERROR", "`provider` must be 'fal.ai'.")
    if sort_by is not None:
        if not isinstance(sort_by, str) or sort_by not in ("created_at", "updated_at", "display_name", "model_id"):
            return _err("VALIDATION_ERROR", "`sort_by` must be one of: created_at, updated_at, display_name, model_id.")
    if sort_order is not None:
        if not isinstance(sort_order, str) or sort_order not in ("asc", "desc"):
            return _err("VALIDATION_ERROR", "`sort_order` must be 'asc' or 'desc'.")
    if limit is not None:
        if not isinstance(limit, int) or limit < 1 or limit > 100:
            return _err("VALIDATION_ERROR", "`limit` must be an integer between 1 and 100.")
    else:
        limit = 50
    off = _decode_cursor(cursor)
    if off is None:
        return _err("VALIDATION_ERROR", "Malformed `cursor`.")

    api_key_row, project_row = _choose_auth_context()
    if not api_key_row:
        # No usable ambient auth context in store
        return _err("UNAUTHORIZED", "No active API key/project available for this operation.")

    rl_err = _enforce_rate_limit(api_key_row)
    if rl_err:
        _record_call("models", api_key_row.get("id"), project_row.get("id"), "RATE_LIMIT")
        return rl_err

    # Apply filters / business rules
    rows = _load("models.json")
    if not isinstance(rows, list):
        rows = []
    q = (keywords or "").strip().lower()
    t = (tag or "").strip().lower()

    filtered = []
    for m in rows:
        if not isinstance(m, dict):
            continue
        m_status = m.get("status")
        # default exclusion of disabled unless explicit status filter includes it
        if status is None:
            if m_status not in ("active", "deprecated"):
                continue
        else:
            if m_status != status:
                continue
        if provider is not None and m.get("provider") != provider:
            continue
        if t:
            tags = m.get("tags")
            if not isinstance(tags, list):
                tags = []
            tags_l = [str(x).lower() for x in tags]
            if t not in tags_l:
                continue
        if q:
            hay = " ".join([
                str(m.get("model_id") or ""),
                str(m.get("display_name") or ""),
                str(m.get("description") or ""),
                " ".join([str(x) for x in (m.get("tags") if isinstance(m.get("tags"), list) else [])]),
            ]).lower()
            if q not in hay:
                continue
        filtered.append(m)

    # Sorting
    sb = sort_by or "display_name"
    so = sort_order or "asc"
    def _k(x):
        v = x.get(sb)
        return "" if v is None else str(v).lower() if isinstance(v, str) else str(v)
    filtered.sort(key=_k, reverse=(so == "desc"))

    total = len(filtered)
    page = filtered[off:off + limit]
    next_off = off + len(page)
    has_more = next_off < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"o:{next_off}".encode("utf-8")).decode("utf-8").rstrip("=")

    # Update key last_used_at
    api_keys = _load("api_keys.json")
    if isinstance(api_keys, list):
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == api_key_row.get("id"):
                k["last_used_at"] = now
                k["updated_at"] = now
                break
        _save("api_keys.json", api_keys)

    _record_call("models", api_key_row.get("id"), project_row.get("id"), "OK")
    return {
        "data": page,
        "meta": {"total": total, "limit": limit, "cursor": cursor, "has_more": has_more, "next_cursor": next_cursor}
    }

