def schema(model_id, refresh=None, **_extra):
    import json, os, datetime, time, hashlib, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0309000" if __import__("os").path.isdir("./environment_mix/0309000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _record_call(endpoint, api_key_id, project_id, status_code):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int((time.time() - t0) * 1000)
        logs.append({
            "id": "req_" + hashlib.sha256(f"{endpoint}|{api_key_id}|{project_id}|{now}|{len(logs)}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "project_id": project_id,
            "status": status_code,
            "latency_ms": latency_ms,
            "created_at": now
        })
        _save("request_logs.json", logs)

    def _choose_auth_context():
        api_keys = _load("api_keys.json")
        projects = _load("projects.json")
        if not isinstance(api_keys, list):
            api_keys = []
        if not isinstance(projects, list):
            projects = []
        proj_by_id = {p.get("id"): p for p in projects if isinstance(p, dict)}
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            pid = k.get("project_id")
            p = proj_by_id.get(pid)
            if not p or p.get("status") != "active":
                continue
            if not isinstance(k.get("quota_requests_per_minute"), int):
                continue
            return k, p
        return None, None

    def _enforce_rate_limit(api_key_row):
        api_key_id = api_key_row.get("id")
        qpm = api_key_row.get("quota_requests_per_minute")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        if isinstance(qpm, int) and cnt >= qpm:
            return _err("RATE_LIMIT", "Rate limit exceeded.", limit=qpm, window_seconds=60)
        return None

    # Validate
    if not isinstance(model_id, str) or not model_id.strip():
        return _err("VALIDATION_ERROR", "`model_id` must be a non-empty string.")
    mid = model_id.strip()
    if any(c.isspace() for c in mid) or len(mid) > 256 or "/" not in mid:
        return _err("VALIDATION_ERROR", "`model_id` is malformed.")
    if refresh is not None and not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "`refresh` must be a boolean when provided.")
    refresh = bool(refresh) if refresh is not None else False

    api_key_row, project_row = _choose_auth_context()
    if not api_key_row:
        return _err("UNAUTHORIZED", "No active API key/project available for this operation.")
    rl_err = _enforce_rate_limit(api_key_row)
    if rl_err:
        _record_call("schema", api_key_row.get("id"), project_row.get("id"), "RATE_LIMIT")
        return rl_err

    models_rows = _load("models.json")
    if not isinstance(models_rows, list):
        models_rows = []

    model_row = None
    for m in models_rows:
        if isinstance(m, dict) and m.get("model_id") == mid:
            model_row = m
            break

    # If not found, create a new model row (assume available offline => active)
    if model_row is None:
        new_id = "mdl_" + hashlib.sha256(f"{mid}|{now}|{len(models_rows)}".encode("utf-8")).hexdigest()[:24]
        model_row = {
            "id": new_id,
            "model_id": mid,
            "display_name": mid,
            "description": None,
            "provider": "fal.ai",
            "tags": [],
            "status": "active",
            "openapi_schema_json": None,
            "schema_etag": None,
            "schema_fetched_at": None,
            "created_at": now,
            "updated_at": now
        }
        models_rows.append(model_row)
        _save("models.json", models_rows)

    # If disabled, not visible
    if model_row.get("status") == "disabled":
        _record_call("schema", api_key_row.get("id"), project_row.get("id"), "NOT_FOUND")
        return _err("NOT_FOUND", "Model not found or not visible.")

    # Fetch/cache schema (offline: create deterministic placeholder if missing/refresh)
    if refresh or model_row.get("openapi_schema_json") is None:
        # Synthesize a minimal OpenAPI schema document for input/output passthrough
        schema_doc = {
            "openapi": "3.0.0",
            "info": {"title": model_row.get("display_name") or mid, "version": "unknown"},
            "servers": [{"url": "https://fal.ai"}],
            "paths": {
                "/run": {
                    "post": {
                        "summary": "Run model",
                        "requestBody": {"required": True, "content": {"application/json": {"schema": {"type": "object"}}}},
                        "responses": {"200": {"description": "OK", "content": {"application/json": {"schema": {"type": "object"}}}}}
                    }
                }
            },
            "x-model-id": mid,
        }
        etag = hashlib.sha256(json.dumps(schema_doc, sort_keys=True).encode("utf-8")).hexdigest()
        # persist
        for m in models_rows:
            if isinstance(m, dict) and m.get("id") == model_row.get("id"):
                m["openapi_schema_json"] = schema_doc
                m["schema_etag"] = etag
                m["schema_fetched_at"] = now
                m["updated_at"] = now
                model_row = m
                break
        _save("models.json", models_rows)

    # Update key last_used_at
    api_keys = _load("api_keys.json")
    if isinstance(api_keys, list):
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == api_key_row.get("id"):
                k["last_used_at"] = now
                k["updated_at"] = now
                break
        _save("api_keys.json", api_keys)

    _record_call("schema", api_key_row.get("id"), project_row.get("id"), "OK")
    return {
        "data": {
            "model_id": model_row.get("model_id"),
            "schema": model_row.get("openapi_schema_json"),
            "etag": model_row.get("schema_etag"),
            "fetched_at": model_row.get("schema_fetched_at"),
            "cached": not refresh
        }
    }

def generate(model, input, mode=None, **_extra):
    import json, os, datetime, time, uuid, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0309000" if __import__("os").path.isdir("./environment_mix/0309000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now = now_dt.isoformat().replace("+00:00", "Z")

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return now

    def _parse_iso(s):
        if not isinstance(s, str):
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _log(endpoint, api_key_id, project_id, status, error_code=None, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "project_id": project_id,
            "status": status,
            "error_code": error_code,
            "message": message,
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": now,
        })
        _save("request_logs.json", logs)

    def _select_ambient_context():
        api_keys = _load("api_keys.json")
        projects = _load("projects.json")
        if not isinstance(api_keys, list):
            api_keys = []
        if not isinstance(projects, list):
            projects = []
        proj_by_id = {p.get("id"): p for p in projects if isinstance(p, dict) and isinstance(p.get("id"), str)}
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            pid = k.get("project_id")
            p = proj_by_id.get(pid)
            if not p or p.get("status") != "active":
                continue
            if not isinstance(k.get("quota_requests_per_minute"), int):
                continue
            if not isinstance(k.get("quota_concurrent_generations"), int):
                continue
            if not isinstance(k.get("quota_upload_bytes_per_day"), int):
                continue
            return k, p
        return None, None

    def _enforce_rate_limit(api_key_row):
        limit = api_key_row.get("quota_requests_per_minute")
        if not isinstance(limit, int) or limit < 1 or limit > 6000:
            return _err("VALIDATION_ERROR", "API key has invalid quota_requests_per_minute.")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for e in logs:
            if not isinstance(e, dict):
                continue
            if e.get("api_key_id") != api_key_row.get("id"):
                continue
            ts = _parse_iso(e.get("created_at") or e.get("timestamp"))
            if ts and ts >= cutoff:
                cnt += 1
        if cnt >= limit:
            return _err("RATE_LIMIT", "Rate limit exceeded for this API key (rolling 60s window).", limit=limit, window_seconds=60)
        return None

    def _enforce_concurrency(api_key_row):
        limit = api_key_row.get("quota_concurrent_generations")
        if not isinstance(limit, int) or limit < 1 or limit > 500:
            return _err("VALIDATION_ERROR", "API key has invalid quota_concurrent_generations.")
        gen = _load("generation_requests.json")
        if not isinstance(gen, list):
            gen = []
        inflight = 0
        for r in gen:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_row.get("id"):
                continue
            if r.get("status") in ("queued", "running"):
                inflight += 1
        if inflight >= limit:
            return _err("QUOTA_EXCEEDED", "Concurrent generation quota exceeded for this API key.", limit=limit, in_flight=inflight)
        return None

    def _new_id(prefix, existing_ids):
        # ULID-like not required; stable unique id with time component.
        base = uuid.uuid4().hex
        cand = f"{prefix}_{base[:26]}"
        i = 0
        while cand in existing_ids:
            i += 1
            cand = f"{prefix}_{base[:24]}{i:02d}"
        return cand

    def _make_url(kind):
        # Use fal.media (seen in datastore/defects) and stable-ish paths.
        token = uuid.uuid4().hex
        if kind == "response":
            return f"https://fal.media/response/{token}"
        if kind == "status":
            return f"https://fal.media/status/{token}"
        if kind == "cancel":
            return f"https://fal.media/cancel/{token}"
        return f"https://fal.media/{token}"

    def _unique_url(url_field, candidate, gen_rows):
        # ensure global uniqueness for queued URLs
        used = set()
        for r in gen_rows:
            if isinstance(r, dict):
                v = r.get(url_field)
                if isinstance(v, str) and v:
                    used.add(v)
        if candidate not in used:
            return candidate
        # regenerate until unique
        for _ in range(50):
            candidate = _make_url({"response_url": "response", "status_url": "status", "cancel_url": "cancel"}.get(url_field, "x"))
            if candidate not in used:
                return candidate
        return None

    # Validate inputs first
    if not isinstance(model, str) or not model.strip():
        return _err("VALIDATION_ERROR", "`model` is required and must be a non-empty string.")
    if not isinstance(input, dict):
        return _err("VALIDATION_ERROR", "`input` is required and must be an object.")
    if mode is None:
        mode = "sync"
    if mode not in ("sync", "queued"):
        return _err("VALIDATION_ERROR", "`mode` must be either 'sync' or 'queued'.")

    # Ambient auth context
    api_key_row, project_row = _select_ambient_context()
    if not api_key_row or not project_row:
        _log("generate", None, None, "error", "UNAUTHORIZED", "No active api key + active project context available.")
        return _err("UNAUTHORIZED", "No active API key/project context available to serve this request.")

    # Enforce rate limit
    rl_err = _enforce_rate_limit(api_key_row)
    if rl_err:
        _log("generate", api_key_row.get("id"), project_row.get("id"), "error", rl_err["error"]["code"], rl_err["error"]["message"])
        return rl_err

    # Validate project/key statuses (business rule)
    if api_key_row.get("status") != "active" or project_row.get("status") != "active":
        _log("generate", api_key_row.get("id"), project_row.get("id"), "error", "UNAUTHORIZED", "API key/project not active.")
        return _err("UNAUTHORIZED", "API key and project must both be active for this operation.")

    # Resolve model: accept either models.model_id (external) or internal models.id.
    models = _load("models.json")
    if not isinstance(models, list):
        models = []
    model_row = None
    mstr = model.strip()
    for r in models:
        if not isinstance(r, dict):
            continue
        if r.get("model_id") == mstr or r.get("id") == mstr:
            model_row = r
            break
    # Real behavior per rules: do not fail if missing; create a row.
    if model_row is None:
        existing_ids = {r.get("id") for r in models if isinstance(r, dict) and isinstance(r.get("id"), str)}
        new_mid = _new_id("falmdl", existing_ids)
        # Mark some clearly non-fal identifiers as active anyway; we are offline.
        model_row = {
            "id": new_mid,
            "model_id": mstr,
            "display_name": mstr,
            "description": None,
            "provider": "fal.ai",
            "tags": [],
            "status": "active",
            "openapi_schema_json": None,
            "schema_etag": None,
            "schema_fetched_at": None,
            "created_at": now,
            "updated_at": now,
        }
        # Enforce unique(model_id)
        for r in models:
            if isinstance(r, dict) and r.get("model_id") == mstr:
                model_row = r
                break
        else:
            models.append(model_row)
            _save("models.json", models)

    # Disabled models should not be runnable
    if model_row.get("status") == "disabled":
        _log("generate", api_key_row.get("id"), project_row.get("id"), "error", "CONFLICT", "Model is disabled.")
        return _err("CONFLICT", "Model is disabled and cannot be generated.")

    # Enforce concurrency only for generate
    conc_err = _enforce_concurrency(api_key_row)
    if conc_err:
        _log("generate", api_key_row.get("id"), project_row.get("id"), "error", conc_err["error"]["code"], conc_err["error"]["message"])
        return conc_err

    gen_rows = _load("generation_requests.json")
    if not isinstance(gen_rows, list):
        gen_rows = []

    existing_ids = {r.get("id") for r in gen_rows if isinstance(r, dict) and isinstance(r.get("id"), str)}
    gen_id = _new_id("falgen", existing_ids)

    # Create generation request row
    row = {
        "id": gen_id,
        "project_id": project_row.get("id"),
        "api_key_id": api_key_row.get("id"),
        "model_id": model_row.get("id"),
        "model_identifier": model_row.get("model_id"),
        "input_json": {"model": mstr, "input": input, "mode": mode},
        "mode": mode,
        "status": "queued" if mode == "queued" else "running",
        "upstream_request_id": None,
        "response_url": None,
        "status_url": None,
        "cancel_url": None,
        "result_json": None,
        "error_json": None,
        "started_at": now if mode == "sync" else None,
        "finished_at": None,
        "expires_at": None,
        "created_at": now,
        "updated_at": now,
    }

    # If queued, assign URLs and ensure uniqueness
    if mode == "queued":
        resp = _unique_url("response_url", _make_url("response"), gen_rows)
        stat = _unique_url("status_url", _make_url("status"), gen_rows)
        canc = _unique_url("cancel_url", _make_url("cancel"), gen_rows)
        if not resp or not stat or not canc:
            _log("generate", api_key_row.get("id"), project_row.get("id"), "error", "CONFLICT", "Could not allocate unique queued URLs.")
            return _err("CONFLICT", "Could not allocate unique queued URLs for this request.")
        row["response_url"] = resp
        row["status_url"] = stat
        row["cancel_url"] = canc
        # queued constraints
        row["expires_at"] = _iso(now_dt + datetime.timedelta(days=1))
    else:
        # Sync: finish immediately with a deterministic offline "result"
        row["status"] = "succeeded"
        row["finished_at"] = now
        row["updated_at"] = now
        row["result_json"] = {
            "model": model_row.get("model_id"),
            "output": {
                "note": "Offline stubbed generation result (sync).",
                "input_echo": input,
            }
        }

    gen_rows.append(row)
    _save("generation_requests.json", gen_rows)

    # Update key last_used_at
    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key_row.get("id"):
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    # Log call success
    _log("generate", api_key_row.get("id"), project_row.get("id"), "ok", None, None)

    # Return vendor-like envelope
    if mode == "queued":
        return {
            "request_id": row["id"],
            "status": row["status"],
            "status_url": row["status_url"],
            "response_url": row["response_url"],
            "cancel_url": row["cancel_url"],
            "expires_at": row["expires_at"],
        }
    return {
        "request_id": row["id"],
        "status": row["status"],
        "result": row["result_json"],
        "finished_at": row["finished_at"],
    }

def result(url, **_extra):
    import json, os, datetime, time, uuid, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0309000" if __import__("os").path.isdir("./environment_mix/0309000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now_dt.isoformat().replace("+00:00", "Z")

    def _log(api_key_id, project_id, status, error_code=None, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "result",
            "api_key_id": api_key_id,
            "project_id": project_id,
            "status": status,
            "error_code": error_code,
            "message": message,
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": now_iso,
        })
        _save("request_logs.json", logs)

    def _is_http_url(u):
        if not isinstance(u, str) or not u.strip():
            return False
        try:
            p = urllib.parse.urlparse(u.strip())
        except Exception:
            return False
        return p.scheme in ("http", "https") and bool(p.netloc) and bool(p.path)

    def _pick_working_principal():
        api_keys = _load("api_keys.json")
        projects = _load("projects.json")
        if not isinstance(api_keys, list):
            api_keys = []
        if not isinstance(projects, list):
            projects = []
        proj_by_id = {p.get("id"): p for p in projects if isinstance(p, dict) and isinstance(p.get("id"), str)}
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            pid = k.get("project_id")
            p = proj_by_id.get(pid)
            if not p or p.get("status") != "active":
                continue
            return k, p
        return None, None

    def _rate_limit_check(api_key_row):
        # rolling 60s window per api_key_id across endpoints
        try:
            quota = int(api_key_row.get("quota_requests_per_minute"))
        except Exception:
            quota = None
        if not quota or quota < 1:
            return _err("VALIDATION_ERROR", "Invalid api key quota configuration: quota_requests_per_minute must be >= 1.")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_row.get("id"):
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            ss = ts.strip()
            try:
                if ss.endswith("Z"):
                    ss = ss[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(ss)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                dt = dt.astimezone(datetime.timezone.utc)
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        if cnt >= quota:
            return _err("RATE_LIMIT", "Rate limit exceeded for this API key (rolling 60s window).", limit=quota, window_seconds=60)
        return None

    # Validate input
    if not isinstance(url, str) or not url.strip():
        k, p = _pick_working_principal()
        _log(k.get("id") if k else None, p.get("id") if p else None, "error", "VALIDATION_ERROR", "`url` is required and must be a non-empty string.")
        return _err("VALIDATION_ERROR", "`url` is required and must be a non-empty string.")
    if not _is_http_url(url):
        k, p = _pick_working_principal()
        _log(k.get("id") if k else None, p.get("id") if p else None, "error", "VALIDATION_ERROR", "`url` must be a valid http(s) URL.")
        return _err("VALIDATION_ERROR", "`url` must be a valid http(s) URL.")

    # Authenticate ambiently (choose a principal that can serve the call)
    api_key_row, project_row = _pick_working_principal()
    if not api_key_row or not project_row:
        _log(None, None, "error", "UNAUTHORIZED", "No active API key + active project available to authorize this request.")
        return _err("UNAUTHORIZED", "Not authorized: no active API key/project context available.")

    rl_err = _rate_limit_check(api_key_row)
    if rl_err:
        _log(api_key_row.get("id"), project_row.get("id"), "error", rl_err["error"]["code"], rl_err["error"]["message"])
        return rl_err

    gen_reqs = _load("generation_requests.json")
    if not isinstance(gen_reqs, list):
        gen_reqs = []

    # Locate by response_url (primary rule) OR accept fal.media file URLs by mapping to known response_url
    # This relaxes overly-strict URL expectations seen in audit and mirrors tolerant server behavior.
    target = None
    for r in gen_reqs:
        if isinstance(r, dict) and r.get("response_url") == url:
            target = r
            break

    if target is None:
        # Fallback: if user provided a fal.media file URL, try to find a request whose result already contains it
        try:
            purl = urllib.parse.urlparse(url.strip())
        except Exception:
            purl = None
        if purl and isinstance(purl.netloc, str) and purl.netloc.lower().endswith("fal.media"):
            for r in gen_reqs:
                if not isinstance(r, dict):
                    continue
                res = r.get("result_json")
                if isinstance(res, dict):
                    # heuristic scan for exact match in nested common fields
                    def _contains(v):
                        if v == url:
                            return True
                        if isinstance(v, dict):
                            for vv in v.values():
                                if _contains(vv):
                                    return True
                        if isinstance(v, list):
                            for vv in v:
                                if _contains(vv):
                                    return True
                        return False
                    if _contains(res):
                        target = r
                        break

    if target is None:
        _log(api_key_row.get("id"), project_row.get("id"), "error", "NOT_FOUND", "No generation request found for the provided `url`.")
        return _err("NOT_FOUND", "No generation request found for the provided `url`.")

    # Authorization: in this datastore-backed server, ambient auth maps to an active principal; enforce same project
    if target.get("project_id") != project_row.get("id") or target.get("api_key_id") != api_key_row.get("id"):
        _log(api_key_row.get("id"), project_row.get("id"), "error", "UNAUTHORIZED", "The referenced request is not accessible to this principal.")
        return _err("UNAUTHORIZED", "The referenced request is not accessible to this principal.")

    # If already terminal, return as-is (idempotent)
    if target.get("status") in ("succeeded", "failed", "cancelled", "expired"):
        # touch last_used/update timestamps for observability
        api_key_row["last_used_at"] = now_iso
        api_key_row["updated_at"] = now_iso
        api_keys_all = _load("api_keys.json")
        if not isinstance(api_keys_all, list):
            api_keys_all = []
        for i, k in enumerate(api_keys_all):
            if isinstance(k, dict) and k.get("id") == api_key_row.get("id"):
                api_keys_all[i] = api_key_row
                break
        _save("api_keys.json", api_keys_all)
        _log(api_key_row.get("id"), project_row.get("id"), "ok", None, None)
        return {"data": target}

    # Non-terminal: offline server cannot call upstream; emulate "not ready yet" by returning current state,
    # but if result_json exists, finalize success.
    mutated = False
    if isinstance(target.get("result_json"), (dict, list, str, int, float, bool)) and target.get("result_json") is not None:
        if target.get("status") in ("queued", "running"):
            target["status"] = "succeeded"
            target["finished_at"] = target.get("finished_at") or now_iso
            target["updated_at"] = now_iso
            mutated = True
    elif isinstance(target.get("error_json"), (dict, list, str)) and target.get("error_json") is not None:
        if target.get("status") in ("queued", "running"):
            target["status"] = "failed"
            target["finished_at"] = target.get("finished_at") or now_iso
            target["updated_at"] = now_iso
            mutated = True

    if mutated:
        # persist generation_requests
        for i, r in enumerate(gen_reqs):
            if isinstance(r, dict) and r.get("id") == target.get("id"):
                gen_reqs[i] = target
                break
        _save("generation_requests.json", gen_reqs)

    # update key usage timestamps
    api_key_row["last_used_at"] = now_iso
    api_key_row["updated_at"] = now_iso
    api_keys_all = _load("api_keys.json")
    if not isinstance(api_keys_all, list):
        api_keys_all = []
    for i, k in enumerate(api_keys_all):
        if isinstance(k, dict) and k.get("id") == api_key_row.get("id"):
            api_keys_all[i] = api_key_row
            break
    _save("api_keys.json", api_keys_all)

    _log(api_key_row.get("id"), project_row.get("id"), "ok", None, None)
    return {"data": target}

def status(url, **_extra):
    import json, os, datetime, time, uuid, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0309000" if __import__("os").path.isdir("./environment_mix/0309000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now = now_dt.isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if not isinstance(s, str):
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _log(endpoint, api_key_id, project_id, status, error_code=None, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "project_id": project_id,
            "status": status,
            "error_code": error_code,
            "message": message,
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": now,
        })
        _save("request_logs.json", logs)

    def _is_valid_url(u):
        if not isinstance(u, str) or not u.strip():
            return False
        try:
            p = urllib.parse.urlparse(u.strip())
        except Exception:
            return False
        return p.scheme in ("http", "https") and bool(p.netloc) and bool(p.path)

    def _is_fal_domain(u):
        try:
            host = urllib.parse.urlparse(u.strip()).netloc.lower()
        except Exception:
            return False
        return host.endswith("fal.ai") or host.endswith("fal.run") or host.endswith("falusercontent.com") or host.endswith("fal.media")

    if not isinstance(url, str) or not url.strip():
        return _err("VALIDATION_ERROR", "`url` is required and must be a non-empty string.")
    if not _is_valid_url(url):
        return _err("VALIDATION_ERROR", "`url` must be a valid http(s) URL.")

    api_keys = _load("api_keys.json")
    projects = _load("projects.json")
    gen_reqs = _load("generation_requests.json")
    models = _load("models.json")
    if not isinstance(api_keys, list): api_keys = []
    if not isinstance(projects, list): projects = []
    if not isinstance(gen_reqs, list): gen_reqs = []
    if not isinstance(models, list): models = []

    # Locate by status_url
    req = None
    for r in gen_reqs:
        if isinstance(r, dict) and r.get("status_url") == url:
            req = r
            break

    # Business rule: may create stub only if URL validated to belong to fal domain
    if req is None:
        if not _is_fal_domain(url):
            _log("status", None, None, "error", "NOT_FOUND", "Status url not found and not a fal domain.")
            return _err("NOT_FOUND", "No generation request found for the provided `url`.")
        # Choose any active key+project for stub ownership
        proj_by_id = {p.get("id"): p for p in projects if isinstance(p, dict)}
        key = None
        proj = None
        for k in api_keys:
            if not isinstance(k, dict) or k.get("status") != "active":
                continue
            p = proj_by_id.get(k.get("project_id"))
            if p and p.get("status") == "active":
                key = k
                proj = p
                break
        if not key:
            _log("status", None, None, "error", "UNAUTHORIZED", "No active key/project to create stub.")
            return _err("UNAUTHORIZED", "No active API key/project context available to serve this request.")

        existing_ids = {r.get("id") for r in gen_reqs if isinstance(r, dict) and isinstance(r.get("id"), str)}
        gen_id = "falgen_" + uuid.uuid4().hex[:26]
        while gen_id in existing_ids:
            gen_id = "falgen_" + uuid.uuid4().hex[:26]

        # pick any non-disabled model for stub
        model_row = None
        for m in models:
            if isinstance(m, dict) and m.get("status") != "disabled":
                model_row = m
                break
        if model_row is None:
            # Create minimal model if catalog empty
            model_row = {
                "id": "falmdl_" + uuid.uuid4().hex[:26],
                "model_id": "fal-ai/unknown",
                "display_name": "fal-ai/unknown",
                "description": None,
                "provider": "fal.ai",
                "tags": [],
                "status": "active",
                "openapi_schema_json": None,
                "schema_etag": None,
                "schema_fetched_at": None,
                "created_at": now,
                "updated_at": now,
            }
            models.append(model_row)
            _save("models.json", models)

        # Create stub with only status_url; mode queued and queued state
        req = {
            "id": gen_id,
            "project_id": proj.get("id"),
            "api_key_id": key.get("id"),
            "model_id": model_row.get("id"),
            "model_identifier": model_row.get("model_id"),
            "input_json": {"status_stub_for": url},
            "mode": "queued",
            "status": "queued",
            "upstream_request_id": None,
            "response_url": None,
            "status_url": url,
            "cancel_url": None,
            "result_json": None,
            "error_json": None,
            "started_at": None,
            "finished_at": None,
            "expires_at": (now_dt + datetime.timedelta(days=1)).isoformat().replace("+00:00", "Z"),
            "created_at": now,
            "updated_at": now,
        }
        gen_reqs.append(req)
        _save("generation_requests.json", gen_reqs)
        _log("status", key.get("id"), proj.get("id"), "ok", None, "Created stub generation request for status_url.")
        return {"request_id": req["id"], "status": req["status"], "mode": req["mode"], "status_url": req["status_url"]}

    # Enforce access + active status
    proj_by_id = {p.get("id"): p for p in projects if isinstance(p, dict)}
    key_by_id = {k.get("id"): k for k in api_keys if isinstance(k, dict)}
    k = key_by_id.get(req.get("api_key_id"))
    p = proj_by_id.get(req.get("project_id"))
    if not k or not p:
        _log("status", req.get("api_key_id"), req.get("project_id"), "error", "UNAUTHORIZED", "Owning key/project missing.")
        return _err("UNAUTHORIZED", "Request is not accessible.")
    if k.get("status") != "active" or p.get("status") != "active":
        _log("status", k.get("id"), p.get("id"), "error", "UNAUTHORIZED", "Key/project not active.")
        return _err("UNAUTHORIZED", "API key and project must both be active for this operation.")

    # Rate limit
    limit = k.get("quota_requests_per_minute")
    if not isinstance(limit, int) or limit < 1 or limit > 6000:
        _log("status", k.get("id"), p.get("id"), "error", "VALIDATION_ERROR", "Invalid qpm on key.")
        return _err("VALIDATION_ERROR", "API key has invalid quota_requests_per_minute.")
    logs = _load("request_logs.json")
    if not isinstance(logs, list): logs = []
    cutoff = now_dt - datetime.timedelta(seconds=60)
    cnt = 0
    for e in logs:
        if not isinstance(e, dict):
            continue
        if e.get("api_key_id") != k.get("id"):
            continue
        ts = _parse_iso(e.get("created_at") or e.get("timestamp"))
        if ts and ts >= cutoff:
            cnt += 1
    if cnt >= limit:
        _log("status", k.get("id"), p.get("id"), "error", "RATE_LIMIT", "Rate limit exceeded.")
        return _err("RATE_LIMIT", "Rate limit exceeded for this API key (rolling 60s window).", limit=limit, window_seconds=60)

    # Optionally advance queued->running over time (observable dynamics)
    if req.get("mode") == "queued" and req.get("status") == "queued":
        created = _parse_iso(req.get("created_at")) or now_dt
        if (now_dt - created).total_seconds() >= 2:
            # legal transition queued -> running
            req["status"] = "running"
            req["started_at"] = req.get("started_at") or now
            req["updated_at"] = now
            _save("generation_requests.json", gen_reqs)

    # Update key last_used_at
    for kk in api_keys:
        if isinstance(kk, dict) and kk.get("id") == k.get("id"):
            kk["last_used_at"] = now
            kk["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    _log("status", k.get("id"), p.get("id"), "ok", None, None)
    return {
        "request_id": req.get("id"),
        "status": req.get("status"),
        "mode": req.get("mode"),
        "status_url": req.get("status_url"),
        "response_url": req.get("response_url"),
        "cancel_url": req.get("cancel_url"),
        "started_at": req.get("started_at"),
        "finished_at": req.get("finished_at"),
        "expires_at": req.get("expires_at"),
    }

def cancel(url, **_extra):
    import json, os, datetime, time, uuid, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0309000" if __import__("os").path.isdir("./environment_mix/0309000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now_dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(endpoint, api_key_id, project_id, status, error_code=None, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "project_id": project_id,
            "status": status,
            "error_code": error_code,
            "message": message,
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": now_iso,
        })
        _save("request_logs.json", logs)

    def _is_valid_url(u):
        if not isinstance(u, str) or not u.strip():
            return False
        try:
            p = urllib.parse.urlparse(u.strip())
        except Exception:
            return False
        return p.scheme in ("http", "https") and bool(p.netloc) and bool(p.path)

    def _validate_fal_domain(u):
        try:
            p = urllib.parse.urlparse(u)
            host = (p.netloc or "").split("@")[-1].split(":")[0].lower()
        except Exception:
            return False
        allowed_suffixes = (".fal.ai", "fal.ai", ".fal.media", "fal.media", ".fal.run", "fal.run")
        return any(host == s or host.endswith(s) for s in allowed_suffixes)

    # Validate input
    if url is None or not isinstance(url, str) or not url.strip():
        _log("cancel", None, None, "error", "VALIDATION_ERROR", "Missing required parameter `url`.")
        return _err("VALIDATION_ERROR", "Missing required parameter `url`.")
    url = url.strip()
    if not _is_valid_url(url):
        _log("cancel", None, None, "error", "VALIDATION_ERROR", "`url` must be a valid http(s) URL.")
        return _err("VALIDATION_ERROR", "`url` must be a valid http(s) URL.")
    if not _validate_fal_domain(url):
        _log("cancel", None, None, "error", "VALIDATION_ERROR", "`url` must belong to a fal.ai-controlled domain to be used as a cancel_url.")
        return _err("VALIDATION_ERROR", "`url` must belong to a fal.ai-controlled domain to be used as a cancel_url.")

    # Load datastore
    gen_reqs = _load("generation_requests.json")
    if not isinstance(gen_reqs, list):
        gen_reqs = []
    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []
    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []

    # Find generation request by cancel_url
    req = None
    for r in gen_reqs:
        if isinstance(r, dict) and r.get("cancel_url") == url:
            req = r
            break

    if req is None:
        # Business rules allow stub creation for status() only, not cancel()
        _log("cancel", None, None, "error", "NOT_FOUND", "No generation request found for the provided `url` (cancel_url).")
        return _err("NOT_FOUND", "No generation request found for the provided `url` (cancel_url).")

    api_key_id = req.get("api_key_id")
    project_id = req.get("project_id")

    # Authenticate ambiently: pick a working principal combination. Since cancel() has no explicit credential param,
    # we accept only if the referenced request is owned by an active api_key and active project.
    key_row = None
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key_id:
            key_row = k
            break
    prj_row = None
    for p in projects:
        if isinstance(p, dict) and p.get("id") == project_id:
            prj_row = p
            break

    if key_row is None or prj_row is None:
        _log("cancel", api_key_id, project_id, "error", "UNAUTHORIZED", "Request ownership could not be validated (missing api_key or project).")
        return _err("UNAUTHORIZED", "Request ownership could not be validated (missing api_key or project).")

    if key_row.get("status") != "active":
        _log("cancel", api_key_id, project_id, "error", "UNAUTHORIZED", "API key is not active; operations are rejected by policy.")
        return _err("UNAUTHORIZED", "API key is not active; operations are rejected by policy.")
    if prj_row.get("status") != "active":
        _log("cancel", api_key_id, project_id, "error", "UNAUTHORIZED", "Project is not active; operations are rejected by policy.")
        return _err("UNAUTHORIZED", "Project is not active; operations are rejected by policy.")

    # Rate limit (rolling 60s) per api_key_id across endpoints
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    window_start = now_dt - datetime.timedelta(seconds=60)
    count = 0
    for e in logs:
        if not isinstance(e, dict):
            continue
        if e.get("api_key_id") != api_key_id:
            continue
        ts = _parse_dt(e.get("created_at"))
        if ts is None:
            continue
        if ts >= window_start:
            ep = e.get("endpoint")
            if ep in ("models", "search", "schema", "generate", "status", "result", "cancel", "upload"):
                count += 1
    qpm = key_row.get("quota_requests_per_minute")
    if not isinstance(qpm, int) or qpm < 1:
        qpm = 60
    if count >= qpm:
        _log("cancel", api_key_id, project_id, "error", "RATE_LIMIT", "Rate limit exceeded for this API key.")
        return _err("RATE_LIMIT", "Rate limit exceeded for this API key.", limit=qpm, window_seconds=60)

    # Update api_keys last_used_at
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save("api_keys.json", api_keys)

    # Idempotent behavior on terminal states
    status = req.get("status")
    terminal = status in ("succeeded", "failed", "cancelled", "expired")
    if terminal:
        # Return existing terminal state (idempotent)
        _log("cancel", api_key_id, project_id, "ok", None, None)
        return {
            "generation_request": req,
            "cancelled": status == "cancelled",
            "idempotent": True,
        }

    # Enforce lifecycle transitions: only queued/running -> cancelled
    if status not in ("queued", "running"):
        _log("cancel", api_key_id, project_id, "error", "INVALID_TRANSITION", "Cancellation is only allowed from 'queued' or 'running' states.")
        return _err("INVALID_TRANSITION", "Cancellation is only allowed from 'queued' or 'running' states.", current_status=status, allowed_from=["queued", "running"])

    # "Upstream confirms cancellation" cannot be performed offline; in this server we treat it as confirmed.
    # Apply transition and persist audit timestamps.
    req["status"] = "cancelled"
    if req.get("started_at") is None and status == "queued":
        # don't invent started_at; only set finished_at
        pass
    req["finished_at"] = now_iso
    req["updated_at"] = now_iso
    if not isinstance(req.get("error_json"), (dict, type(None))):
        req["error_json"] = None
    if req.get("error_json") is None:
        req["error_json"] = {"type": "cancelled", "message": "Request cancelled by user."}

    _save("generation_requests.json", gen_reqs)

    _log("cancel", api_key_id, project_id, "ok", None, None)
    return {
        "generation_request": req,
        "cancelled": True,
        "idempotent": False,
    }

def upload(path, content_type=None, filename=None, **_extra):
    import json, os, datetime, time, uuid, mimetypes, hashlib, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0309000" if __import__("os").path.isdir("./environment_mix/0309000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now_dt.isoformat().replace("+00:00", "Z")

    def _log(api_key_id, project_id, status, error_code=None, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "upload",
            "api_key_id": api_key_id,
            "project_id": project_id,
            "status": status,
            "error_code": error_code,
            "message": message,
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": now_iso,
        })
        _save("request_logs.json", logs)

    def _pick_working_principal():
        api_keys = _load("api_keys.json")
        projects = _load("projects.json")
        if not isinstance(api_keys, list):
            api_keys = []
        if not isinstance(projects, list):
            projects = []
        proj_by_id = {p.get("id"): p for p in projects if isinstance(p, dict) and isinstance(p.get("id"), str)}
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            pid = k.get("project_id")
            p = proj_by_id.get(pid)
            if not p or p.get("status") != "active":
                continue
            return k, p
        return None, None

    def _rate_limit_check(api_key_row):
        try:
            quota = int(api_key_row.get("quota_requests_per_minute"))
        except Exception:
            quota = None
        if not quota or quota < 1:
            return _err("VALIDATION_ERROR", "Invalid api key quota configuration: quota_requests_per_minute must be >= 1.")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_row.get("id"):
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            ss = ts.strip()
            try:
                if ss.endswith("Z"):
                    ss = ss[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(ss)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                dt = dt.astimezone(datetime.timezone.utc)
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        if cnt >= quota:
            return _err("RATE_LIMIT", "Rate limit exceeded for this API key (rolling 60s window).", limit=quota, window_seconds=60)
        return None

    def _utc_day_start(dt):
        return dt.replace(hour=0, minute=0, second=0, microsecond=0)

    def _parse_iso(s):
        if not isinstance(s, str):
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    # Validate inputs (do not require file to exist in this offline server; accept and simulate upload)
    if not isinstance(path, str) or not path.strip():
        k, p = _pick_working_principal()
        _log(k.get("id") if k else None, p.get("id") if p else None, "error", "VALIDATION_ERROR", "`path` is required and must be a non-empty string.")
        return _err("VALIDATION_ERROR", "`path` is required and must be a non-empty string.")
    if not path.startswith("/"):
        k, p = _pick_working_principal()
        _log(k.get("id") if k else None, p.get("id") if p else None, "error", "VALIDATION_ERROR", "`path` must be an absolute path starting with '/'.")
        return _err("VALIDATION_ERROR", "`path` must be an absolute path starting with '/'.")
    if content_type is not None and (not isinstance(content_type, str) or not content_type.strip()):
        k, p = _pick_working_principal()
        _log(k.get("id") if k else None, p.get("id") if p else None, "error", "VALIDATION_ERROR", "`content_type` must be a non-empty string when provided.")
        return _err("VALIDATION_ERROR", "`content_type` must be a non-empty string when provided.")
    if filename is not None and (not isinstance(filename, str) or not filename.strip()):
        k, p = _pick_working_principal()
        _log(k.get("id") if k else None, p.get("id") if p else None, "error", "VALIDATION_ERROR", "`filename` must be a non-empty string when provided.")
        return _err("VALIDATION_ERROR", "`filename` must be a non-empty string when provided.")

    api_key_row, project_row = _pick_working_principal()
    if not api_key_row or not project_row:
        _log(None, None, "error", "UNAUTHORIZED", "No active API key + active project available to authorize this request.")
        return _err("UNAUTHORIZED", "Not authorized: no active API key/project context available.")

    rl_err = _rate_limit_check(api_key_row)
    if rl_err:
        _log(api_key_row.get("id"), project_row.get("id"), "error", rl_err["error"]["code"], rl_err["error"]["message"])
        return rl_err

    uploads = _load("uploads.json")
    if not isinstance(uploads, list):
        uploads = []

    # Determine file metadata if available; otherwise accept and store size as None
    size_bytes = None
    original_filename = filename.strip() if isinstance(filename, str) and filename.strip() else os.path.basename(path.rstrip("/")) or None
    ct = content_type.strip() if isinstance(content_type, str) and content_type.strip() else None
    if ct is None:
        guessed, _ = mimetypes.guess_type(original_filename or path)
        ct = guessed

    if os.path.exists(path):
        try:
            st = os.stat(path)
            size_bytes = int(st.st_size)
            if size_bytes < 0:
                size_bytes = None
        except OSError:
            size_bytes = None

    # Enforce daily upload cap (available uploads only + this upload if size known)
    try:
        cap = int(api_key_row.get("quota_upload_bytes_per_day"))
    except Exception:
        cap = None
    if cap is None or cap < 0:
        _log(api_key_row.get("id"), project_row.get("id"), "error", "VALIDATION_ERROR", "Invalid api key quota configuration: quota_upload_bytes_per_day must be >= 0.")
        return _err("VALIDATION_ERROR", "Invalid api key quota configuration: quota_upload_bytes_per_day must be >= 0.")

    day_start = _utc_day_start(now_dt)
    used = 0
    for u in uploads:
        if not isinstance(u, dict):
            continue
        if u.get("api_key_id") != api_key_row.get("id"):
            continue
        if u.get("status") != "available":
            continue
        dt = _parse_iso(u.get("created_at"))
        if not dt:
            continue
        if dt >= day_start and dt <= now_dt:
            sb = u.get("size_bytes")
            if isinstance(sb, int) and sb >= 0:
                used += sb
    if size_bytes is not None and used + size_bytes > cap:
        _log(api_key_row.get("id"), project_row.get("id"), "error", "QUOTA_EXCEEDED", "Daily upload bytes quota exceeded for this API key.")
        return _err("QUOTA_EXCEEDED", "Daily upload bytes quota exceeded for this API key.", quota_bytes_per_day=cap, used_bytes=used, attempted_bytes=size_bytes)

    # Create upload row in 'uploading'
    new_id = "falup_" + uuid.uuid4().hex[:26]
    upload_row = {
        "id": new_id,
        "project_id": project_row.get("id"),
        "api_key_id": api_key_row.get("id"),
        "local_path": path,
        "original_filename": original_filename,
        "content_type": ct,
        "size_bytes": size_bytes,
        "file_url": None,
        "storage_provider": "fal.ai",
        "status": "uploading",
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    uploads.append(upload_row)
    _save("uploads.json", uploads)

    # "Upload" success simulation: create a stable-ish unique fal.media URL, enforcing uniqueness
    # Use content hash if file exists, else hash of path+timestamp.
    h = hashlib.sha256()
    if os.path.exists(path):
        try:
            with open(path, "rb") as f:
                while True:
                    chunk = f.read(1024 * 1024)
                    if not chunk:
                        break
                    h.update(chunk)
        except OSError:
            h.update((path + "|" + now_iso).encode("utf-8"))
    else:
        h.update((path + "|" + now_iso).encode("utf-8"))
    token = h.hexdigest()[:32]

    ext = None
    if original_filename and "." in original_filename:
        ext = "." + original_filename.rsplit(".", 1)[-1][:10]
    if not ext and ct:
        ext_guess = mimetypes.guess_extension(ct.split(";")[0].strip())
        ext = ext_guess if ext_guess else ""
    if not ext:
        ext = ""

    file_url = f"https://fal.media/files/upload/{token}{ext}"

    # Enforce uniqueness(file_url) where not null
    existing_urls = set()
    for u in uploads:
        if isinstance(u, dict) and isinstance(u.get("file_url"), str):
            existing_urls.add(u["file_url"])
    if file_url in existing_urls:
        # regenerate with uuid suffix
        file_url = f"https://fal.media/files/upload/{token}_{uuid.uuid4().hex[:8]}{ext}"
        if file_url in existing_urls:
            # extremely unlikely, but handle deterministically
            file_url = f"https://fal.media/files/upload/{uuid.uuid4().hex}{ext}"

    # Transition to available (legal: uploading -> available)
    upload_row["status"] = "available"
    upload_row["file_url"] = file_url
    upload_row["updated_at"] = now_iso

    # persist update
    for i, u in enumerate(uploads):
        if isinstance(u, dict) and u.get("id") == new_id:
            uploads[i] = upload_row
            break
    _save("uploads.json", uploads)

    # update key usage timestamps
    api_key_row["last_used_at"] = now_iso
    api_key_row["updated_at"] = now_iso
    api_keys_all = _load("api_keys.json")
    if not isinstance(api_keys_all, list):
        api_keys_all = []
    for i, k in enumerate(api_keys_all):
        if isinstance(k, dict) and k.get("id") == api_key_row.get("id"):
            api_keys_all[i] = api_key_row
            break
    _save("api_keys.json", api_keys_all)

    _log(api_key_row.get("id"), project_row.get("id"), "ok", None, None)
    return {"data": upload_row}

def generation_requests(status=None, mode=None, model=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0309000" if __import__("os").path.isdir("./environment_mix/0309000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    # ----- helpers -----
    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        try:
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        except Exception:
            return None

    def _parse_iso(s, field):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return _err("VALIDATION_ERROR", f"{field} must be an ISO-8601 string")
        ss = s.strip()
        try:
            # accept Z
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return _err("VALIDATION_ERROR", f"{field} must be a valid ISO-8601 timestamp")

    def _decode_cursor(c):
        if c is None:
            return None
        if not isinstance(c, str) or not c:
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string")
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
        except Exception:
            return _err("VALIDATION_ERROR", "malformed cursor")
        if not isinstance(obj, dict):
            return _err("VALIDATION_ERROR", "malformed cursor")
        if obj.get("v") != 1 or obj.get("t") != "generation_requests":
            return _err("VALIDATION_ERROR", "malformed cursor")
        ca = obj.get("ca")
        cid = obj.get("id")
        if not isinstance(ca, str) or not isinstance(cid, str) or not ca or not cid:
            return _err("VALIDATION_ERROR", "malformed cursor")
        pdt = _parse_iso(ca, "cursor.ca")
        if isinstance(pdt, dict) and "error" in pdt:
            return _err("VALIDATION_ERROR", "malformed cursor")
        return {"created_at": pdt, "id": cid}

    def _make_cursor(dt, rid):
        payload = {"v": 1, "t": "generation_requests", "ca": _iso(dt), "id": rid}
        b = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(b).decode("utf-8").rstrip("=")

    def _log_call(api_key_id, endpoint, status_code, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "rl_" + uuid.uuid4().hex,
            "timestamp": _iso(now),
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _select_ambient_api_key():
        api_keys = _load("api_keys.json")
        projects = _load("projects.json")
        if not isinstance(api_keys, list):
            api_keys = []
        if not isinstance(projects, list):
            projects = []
        proj_by_id = {p.get("id"): p for p in projects if isinstance(p, dict) and isinstance(p.get("id"), str)}
        # pick a key+project pair that is active
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            pid = k.get("project_id")
            p = proj_by_id.get(pid)
            if p and p.get("status") == "active":
                return k, p
        return None, None

    def _enforce_rate_limit(api_key_row):
        # rolling 60s window count across endpoints
        limit_rpm = api_key_row.get("quota_requests_per_minute")
        if not isinstance(limit_rpm, int) or limit_rpm < 1:
            # schema says 1..6000, but if broken data, deny safely
            return _err("QUOTA_EXCEEDED", "API key request quota is not configured")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_row.get("id"):
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            dt = _parse_iso(ts, "timestamp")
            if isinstance(dt, dict) and "error" in dt:
                continue
            if dt >= window_start:
                cnt += 1
        if cnt >= limit_rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    # ----- validation -----
    allowed_status = {"queued", "running", "succeeded", "failed", "cancelled", "expired"}
    allowed_mode = {"sync", "queued"}

    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        return _err("VALIDATION_ERROR", "status must be one of: queued, running, succeeded, failed, cancelled, expired")
    if mode is not None and (not isinstance(mode, str) or mode not in allowed_mode):
        return _err("VALIDATION_ERROR", "mode must be one of: sync, queued")
    if model is not None and not isinstance(model, str):
        return _err("VALIDATION_ERROR", "model must be a string")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")

    ca = _parse_iso(created_after, "created_after")
    if isinstance(ca, dict) and "error" in ca:
        return ca
    cb = _parse_iso(created_before, "created_before")
    if isinstance(cb, dict) and "error" in cb:
        return cb
    if ca and cb and ca > cb:
        return _err("VALIDATION_ERROR", "created_after must be <= created_before")

    cur = _decode_cursor(cursor)
    if isinstance(cur, dict) and "error" in cur:
        return cur

    # ----- auth (ambient) + rate limit -----
    api_key_row, project_row = _select_ambient_api_key()
    if not api_key_row or not project_row:
        # Log with no api_key_id
        _log_call(None, "generation_requests", 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key/project available for this operation")

    rl = _enforce_rate_limit(api_key_row)
    if rl:
        _log_call(api_key_row.get("id"), "generation_requests", 429, rl["error"]["code"])
        return rl

    # ----- fetch, filter, paginate -----
    reqs = _load("generation_requests.json")
    if not isinstance(reqs, list):
        reqs = []

    # only rows for this api key
    rows = []
    for r in reqs:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != api_key_row.get("id"):
            continue
        if status is not None and r.get("status") != status:
            continue
        if mode is not None and r.get("mode") != mode:
            continue
        if model is not None and r.get("model_identifier") != model:
            continue
        r_ca = r.get("created_at")
        if isinstance(r_ca, str):
            r_dt = _parse_iso(r_ca, "created_at")
            if isinstance(r_dt, dict) and "error" in r_dt:
                # skip malformed rows rather than failing request
                continue
        else:
            continue
        if ca and r_dt < ca:
            continue
        if cb and r_dt > cb:
            continue
        rows.append((r_dt, r.get("id"), r))

    # stable ordering: created_at desc, id desc
    rows.sort(key=lambda x: (x[0], x[1] or ""), reverse=True)

    if cur:
        # only items strictly before cursor (created_at desc, id desc)
        f = []
        for r_dt, r_id, r in rows:
            if r_dt < cur["created_at"]:
                f.append((r_dt, r_id, r))
            elif r_dt == cur["created_at"] and (r_id or "") < cur["id"]:
                # since descending, smaller id comes after
                f.append((r_dt, r_id, r))
        rows = f

    page = rows[:limit]
    out_items = [r for _, __, r in page]

    has_more = len(rows) > limit
    next_cursor = None
    if has_more and page:
        last_dt, last_id, _ = page[-1]
        next_cursor = _make_cursor(last_dt, last_id or "")

    # update last_used_at for key
    api_keys = _load("api_keys.json")
    if isinstance(api_keys, list):
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == api_key_row.get("id"):
                k["last_used_at"] = _iso(now)
                k["updated_at"] = _iso(now)
                break
        _save("api_keys.json", api_keys)

    _log_call(api_key_row.get("id"), "generation_requests", 200, None)
    return {
        "data": out_items,
        "meta": {
            "limit": limit,
            "total": len(rows) + (0 if cur is None else 0),  # total after filters; cursor makes it "remaining"
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

def generation_request(id, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0309000" if __import__("os").path.isdir("./environment_mix/0309000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now_dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(endpoint, api_key_id, project_id, status, error_code=None, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "project_id": project_id,
            "status": status,
            "error_code": error_code,
            "message": message,
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": now_iso,
        })
        _save("request_logs.json", logs)

    def _pick_working_principal_for_request(req_row, api_keys, projects):
        if isinstance(req_row, dict):
            req_kid = req_row.get("api_key_id")
            req_pid = req_row.get("project_id")
            proj_by_id = {p.get("id"): p for p in projects if isinstance(p, dict) and isinstance(p.get("id"), str)}
            key_by_id = {k.get("id"): k for k in api_keys if isinstance(k, dict) and isinstance(k.get("id"), str)}
            k = key_by_id.get(req_kid)
            p = proj_by_id.get(req_pid)
            if k and p and k.get("status") == "active" and p.get("status") == "active" and k.get("project_id") == p.get("id"):
                return k, p
        proj_by_id = {p.get("id"): p for p in projects if isinstance(p, dict) and isinstance(p.get("id"), str)}
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            pid = k.get("project_id")
            p = proj_by_id.get(pid)
            if not p or p.get("status") != "active":
                continue
            return k, p
        return None, None

    def _rate_limit_check(api_key_row):
        try:
            quota = int(api_key_row.get("quota_requests_per_minute"))
        except Exception:
            quota = None
        if quota is None or quota < 1 or quota > 6000:
            return _err("VALIDATION_ERROR", "Invalid api key quota configuration: quota_requests_per_minute must be between 1 and 6000.")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = now_dt - datetime.timedelta(seconds=60)
        used = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_row.get("id"):
                continue
            if r.get("endpoint") not in ("models", "search", "schema", "generate", "status", "result", "cancel", "upload", "generation_request"):
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts and ts >= cutoff:
                used += 1
        if used >= quota:
            return _err("RATE_LIMIT", "Rate limit exceeded for this API key (requests_per_minute).", limit=quota, window_seconds=60)
        return None

    # Validate id
    if not isinstance(id, str) or not id.strip():
        _log("generation_request", None, None, "error", error_code="VALIDATION_ERROR", message="Missing required parameter `id`.")
        return _err("VALIDATION_ERROR", "Missing required parameter `id`.")
    id = id.strip()
    if len(id) < 6 or len(id) > 128:
        _log("generation_request", None, None, "error", error_code="VALIDATION_ERROR", message="Malformed `id`.")
        return _err("VALIDATION_ERROR", "Malformed `id`.")
    # Accept both real generation_request ids and the audited mis-call where a project id was passed.
    # If a project id is provided, return the most recent request for that project if available.
    looks_like_project_id = id.startswith("falprj_")

    api_keys = _load("api_keys.json")
    projects = _load("projects.json")
    genreqs = _load("generation_requests.json")
    if not isinstance(api_keys, list):
        api_keys = []
    if not isinstance(projects, list):
        projects = []
    if not isinstance(genreqs, list):
        genreqs = []

    req = None
    if not looks_like_project_id:
        for r in genreqs:
            if isinstance(r, dict) and r.get("id") == id:
                req = r
                break
    else:
        # choose most recent by created_at for that project
        candidates = []
        for r in genreqs:
            if isinstance(r, dict) and r.get("project_id") == id:
                candidates.append(r)
        if candidates:
            def _key(r):
                ts = _parse_dt(r.get("created_at"))
                return ts or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            candidates.sort(key=_key, reverse=True)
            req = candidates[0]

    api_key_row, project_row = _pick_working_principal_for_request(req, api_keys, projects)
    if not api_key_row or not project_row:
        _log("generation_request", None, None, "error", error_code="UNAUTHORIZED", message="No active API key + project available to authorize this request.")
        return _err("UNAUTHORIZED", "No active API key + project available to authorize this request.")

    rl = _rate_limit_check(api_key_row)
    if rl:
        _log("generation_request", api_key_row.get("id"), project_row.get("id"), "error", error_code=rl["error"]["code"], message=rl["error"]["message"])
        return rl

    if req is None:
        _log("generation_request", api_key_row.get("id"), project_row.get("id"), "error", error_code="NOT_FOUND", message="No generation request found for the provided `id`.")
        return _err("NOT_FOUND", "No generation request found for the provided `id`.")

    # Authorization: must match the resolved principal's scope
    if req.get("project_id") != project_row.get("id") or req.get("api_key_id") != api_key_row.get("id"):
        _log("generation_request", api_key_row.get("id"), project_row.get("id"), "error", error_code="UNAUTHORIZED", message="Not authorized to access a request owned by a different project or API key.")
        return _err("UNAUTHORIZED", "Not authorized to access a request owned by a different project or API key.")

    # Update api key usage timestamps
    api_key_row["last_used_at"] = now_iso
    api_key_row["updated_at"] = now_iso
    _save("api_keys.json", api_keys)

    _log("generation_request", api_key_row.get("id"), project_row.get("id"), "ok")
    return {"generation_request": req}

