    if isinstance(api_keys, list):
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == api_key_row.get("id"):
                k["last_used_at"] = _iso(now)
                k["updated_at"] = _iso(now)
                break
        _save("api_keys.json", api_keys)

    _log_call(api_key_row.get("id"), "uploads", 200, None)
    return {
        "data": out_items,
        "meta": {
            "limit": limit,
            "total": len(rows),
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }
